import org.junit.jupiter.api.Test;

class LeftJoinQueryEvaluationStepBindingDomainTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String QUERY = """
			SELECT ?y ?z WHERE {
				VALUES ?k { 1 }
				OPTIONAL {
					VALUES (?y ?z) { (2 3) }
					FILTER(BOUND(?y) && BOUND(?z))
				}
			}
			""";

	@Test
	void serviceResultColumnWithoutABindingDoesNotChangeOptionalScope() {
		BindingSet remote = new ListBindingSet(List.of("seed", "y"), VF.createLiteral(1), null);
		try (var rows = new InsertBindingSetCursor(new SingletonIteration<>(remote), EmptyBindingSet.getInstance())) {
			BindingSet input = rows.next();
			assertThat(input.getBindingNames()).contains("y");
			assertThat(input.hasBinding("y")).isFalse();
			assertOptionalResult(input, LeftJoinIterator.class.getSimpleName());
		}
	}

	@Test
	void suppliedOptionalBindingLeavesOtherConditionBindingsVisible() {
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding("y", VF.createLiteral("2", XSD.INTEGER));
		assertOptionalResult(input, BadlyDesignedLeftJoinIterator.class.getSimpleName());
	}

	@Test
	void explicitNullRemainsPartOfTheIncomingDomain() {
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding("seed", VF.createLiteral(1));
		input.addBinding("y", null);
		assertThat(input.hasBinding("y")).isTrue();
		assertOptionalResult(input, BadlyDesignedLeftJoinIterator.class.getSimpleName());
	}

	private static void assertOptionalResult(BindingSet input, String expectedAlgorithm) {
		var expression = (QueryRoot) new SPARQLParser().parseQuery(QUERY, null).getTupleExpr();
		var optional = (LeftJoin) ((Projection) expression.getArg()).getArg();
		var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		try (var rows = strategy.precompile(expression).evaluate(input)) {
			BindingSet expected = new ListBindingSet(List.of("y", "z"), VF.createLiteral("2", XSD.INTEGER),
					VF.createLiteral("3", XSD.INTEGER));
			assertThat(QueryResults.asList(rows)).containsExactly(expected);
			assertThat(optional.getAlgorithmName()).isEqualTo(expectedAlgorithm);
		}
	}
}
